extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var script: GDScript = load("res://story_player.gd") as GDScript
	if not check("script_loaded", script != null, "Lo script res://story_player.gd deve caricarsi senza errori"):
		return

	var player: Node = script.new() as Node
	add_child(player)

	player.set("story_file_path", "res://story.json")
	player.set("_current_line_index", 4)

	var save_dict: Variant = call_if_exists(player, "get_save_data")
	if check("get_save_data_is_dict", save_dict is Dictionary, "get_save_data() deve restituire un dizionario"):
		var d: Dictionary = save_dict
		check("line_index_correct", int(d.get("line_index", -1)) == 4, "get_save_data() deve salvare l'indice di riga corrente (4), non 0")

	var test_data: Dictionary = {
		"story_file": "res://story.json",
		"line_index": 2,
		"variables": {"gold": 50}
	}

	call_if_exists(player, "restore_from_save", [test_data])
	var vars_val: Variant = player.get("_variables")
	check("vars_restored", vars_val is Dictionary and (vars_val as Dictionary).get("gold", 0) == 50, "restore_from_save() deve ripristinare il dizionario delle variabili dal salvataggio")

	player.queue_free()

